from collections import Counter
def solve(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(v for r in grid for v in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and not seen[i][j]:
                st=[(i,j)];seen[i][j]=True;cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and grid[x][y]!=bg and not seen[x][y]:
                            seen[x][y]=True;st.append((x,y))
                comps.append(cells)
    comps.sort(key=len,reverse=True)
    pat=comps[0]; markers=[c for comp in comps[1:] for c in comp]
    rs=[a for a,b in pat];cs=[b for a,b in pat]
    top,left=min(rs),min(cs); ph,pw=max(rs)-top+1,max(cs)-left+1
    out=[r[:] for r in grid]
    for m in markers:
        r0,c0=m[0]-ph//2,m[1]-pw//2
        for a,b in pat:
            x,y=r0+a-top,c0+b-left
            if 0<=x<h and 0<=y<w: out[x][y]=grid[a][b]
    return out
