def cs(p): return [(i,j,v) for i,r in enumerate(p['g']) for j,v in enumerate(r) if v!=p['bg']]

def near(cells2d, r, c, tie='first'):
    # cells2d list of (i,j); closest to (r,c)
    best=None
    for t in sorted(cells2d):
        d=(t[0]-r)**2+(t[1]-c)**2
        if best is None or d<best[0]: best=(d,t)
    return best[1]

rules={}
def rule(name):
    def deco(f): rules[name]=f; return f
    return deco

@rule('center')
def r1(p): return (len(p['g'])//2, len(p['g'][0])//2)
@rule('centroid comp nearest')
