    c=cs(p); return near([(a,b) for a,b,v in c], sum(a for a,b,v in c)/len(c), sum(b for a,b,v in c)/len(c))
@rule('value-weighted centroid')
def r3(p):
    c=cs(p); W=sum(v for a,b,v in c)
    return near([(a,b) for a,b,v in c], sum(a*v for a,b,v in c)/W, sum(b*v for a,b,v in c)/W)
@rule('inverse-value centroid')
def r4(p):
    c=cs(p); W=sum(1/v for a,b,v in c)
    return near([(a,b) for a,b,v in c], sum(a/v for a,b,v in c)/W, sum(b/v for a,b,v in c)/W)
@rule('rarity-weighted centroid')
def r5(p):
    c=cs(p); cnt=Counter(v for a,b,v in c); W=sum(cnt[v] for a,b,v in c)  # weight=1/cnt -> use cnt as inv
    return near([(a,b) for a,b,v in c], sum(a/cnt[v] for a,b,v in c)/sum(1/cnt[v] for a,b,v in c), sum(b/cnt[v] for a,b,v in c)/sum(1/cnt[v] for a,b,v in c))
def vcell_rule(valf):
    def f(p):
        c=cs(p); cnt=Counter(v for a,b,v in c); vals={v:valf(v,cnt,p) for a,b,v in c}
        V=max(vals, key=vals.get)
        h,w=len(p['g']),len(p['g'][0])
        cand=[(a,b) for a,b,v in c if v==V]
        return near(cand, (len(p['g'])-1)/2, (len(p['g'][0])-1)/2)
    return f
